emitFrame(1, ({ width, height, clear, setPixel }) => {
  clear(0x000000);
  const cellW = width / columns;
  const cellH = height / rows;
  const centerCol = (columns - 1) / 2;
  const centerRow = (rows - 1) / 2;
  const heartSize = Math.min(columns, rows) * 0.8;
  
  for (let col = 0; col < columns; col++) {
    for (let row = 0; row < rows; row++) {
      const x0 = Math.floor(col * cellW);
      const x1 = Math.floor((col + 1) * cellW);
      const y0 = Math.floor(row * cellH);
      const y1 = Math.floor((row + 1) * cellH);
      
      const px = (col - centerCol) / (heartSize * 0.5);
      const py = (centerRow - row) / (heartSize * 0.6);
      const eq = Math.pow(px * px + py * py - 1, 3) - px * px * py * py * py;
      
      if (eq <= 0) {
        const color = 0xff4d4f;
        for (let y = y0; y < y1; y++) {
          for (let x = x0; x < x1; x++) {
            setPixel(x, y, color);
          }
        }
      }
    }
  }
});
